def find_cool_integer(n):
    """Searches for a cool integer sequence for length n."""
    # For small n, permutations are feasible. For larger n, this will be slow.
    # Since n <= 15, we rely on the fact that solutions, if they exist, might be found quickly
    # by permutations if the numbers are small enough, but 15! is too big.
    # We must rely on the backtracking approach implied by the logic, but since itertools.permutations
    # will crash or time out for n > 10, we will proceed cautiously and check up to a practical limit,
    # or rely on the recursive search structure if brute force fails.

    # Let's use a recursive backtracking search instead of itertools.permutations for better performance on average case,
    # although even the backtracking might be slow for n near 15.

    def search(path, remaining_numbers, current_sum):
        if len(path) == n:
            return path

        for next_num in list(remaining_numbers):
            new_sum = current_sum + next_num
            if not is_square(new_sum):
                new_path = path + [next_num]
                new_remaining = remaining_numbers - {next_num}
                result = search(new_path, new_remaining, new_sum)
                if result:
                    return result
        return None

    all_numbers = set(range(1, n + 1))

    # Initial call: Start with an empty path, all numbers remaining, sum 0.
    result = search([], all_numbers, 0)
    return result

