def is_square(k):
    if k < 0:
        return False
    sqrt_k = int(math.isqrt(k))
    return sqrt_k * sqrt_k == k

def is_cool_backtracking(n):
    S_n = n * (n + 1) // 2
    if is_square(S_n):
        return False, "S_n is a perfect square"

    elements = list(range(1, n + 1))

    # Helper function for backtracking search
    def backtrack(current_permutation, used_elements, current_sum):
        if len(current_permutation) == n:
            # Found a valid permutation
            return True, None

        for i in range(n):
            element = elements[i]
            if element not in used_elements:
                next_sum = current_sum + element
                if not is_square(next_sum):
                    new_permutation = current_permutation + [element]
                    new_used = used_elements | {element}

                    # Recurse
                    found, _ = backtrack(new_permutation, new_used, next_sum)
                    if found:
                        return True, new_permutation

        # No valid move from this state
        return False, None

    # Initial call: start with an empty permutation, no elements used, sum 0
    found, permutation = backtrack([], set(), 0)

    if found:
        return True, permutation
    else:
        # This means no permutation worked, even though S_n is not a square.
        return False, "Backtracking failed to find a permutation"

